def write_pair(root, name):
    root = Path(root)
    root.mkdir(parents=True, exist_ok=False)
    fixture = FIXTURES[name]
    for field, entry in fixture['files'].items():
        raw = zlib.decompress(base64.b85decode(entry['base85_zlib']))
        if len(raw) != entry['bytes'] or hashlib.sha256(raw).hexdigest() != entry['sha256']:
            raise ValueError('historical fixture byte identity changed')
        (root / (field + '.json')).write_bytes(raw)
    return root / 'context.json', root / 'run.json', fixture['expected_execution_id']
